  localparam real HMAO_CLK_HALF = 1.25;  // 400 MHz (RTL package default)
  localparam real WDT_CLK_HALF  = 1.852; // 270 MHz
  logic hmao_clk = 1'b0;
  logic wdt_clk  = 1'b0;
  always #(HMAO_CLK_HALF) hmao_clk = ~hmao_clk;
  always #(WDT_CLK_HALF)  wdt_clk  = ~wdt_clk;

  logic hmao_rst_n = 1'b0;
  initial begin
    hmao_rst_n = 1'b0;
    repeat(20) @(posedge hmao_clk);
    hmao_rst_n = 1'b1;
  end

  // ===========================================================================
  // SCOREBOARD
  // ===========================================================================
  int pass_cnt = 0;
  int fail_cnt = 0;
  int boundary_veto_cnt  = 0;   // informational tally, not pass/fail
  int boundary_grant_cnt = 0;

  task automatic check(input string name, input logic cond);
    if (cond) begin pass_cnt++; end
    else begin $error("  FAIL | %s", name); fail_cnt++; end
  endtask

  // ===========================================================================
  // HMAO ENGINE SIGNALS
  // ===========================================================================
  logic        hmao_start    = 1'b0;
  logic [7:0]  gps_quality   = 8'd255;
