    .pipe                      (u_pipe),
    .wdt_clk                   (wdt_clk),
    .hmao_complete             (hmao_complete),
    .hmao_decision_out         (hmao_decision),
    .hmao_violation_out        (hmao_violation),
    .hmao_status_out           (hmao_status),
    .hmao_latency_out          (hmao_latency),
    .lateral_margin_out        (lat_margin),
    .long_margin_out           (long_margin),
    .time_margin_out           (time_margin),
    .irq_clear                 (irq_clear),
    .debug_start_preproc       (dbg_start_preproc),
    .debug_fsm_state_encoded   (dbg_fsm_raw),
    .debug_hmao_start_received (dbg_hmao_start_rx),
    .debug_preproc_valid       (dbg_preproc_valid),
    .debug_preproc_error       (dbg_preproc_error),
    .fault_out                 (fault_out),
    .fault_valid_out           (fault_valid)
  );

  assign hmao_araddr  = u_axi_ro.araddr;
  assign hmao_arlen   = u_axi_ro.arlen;
  assign hmao_arsize  = u_axi_ro.arsize;
  assign hmao_arburst = u_axi_ro.arburst;
  assign hmao_arvalid = u_axi_ro.arvalid;
  assign hmao_aruser  = u_axi_ro.aruser;
  assign hmao_rready  = u_axi_ro.rready;

  assign u_axi_ro.arready = hmao_arready;
  assign u_axi_ro.rid     = '0;
  assign u_axi_ro.rdata   = hmao_rdata;
  assign u_axi_ro.rresp   = hmao_rresp;
  assign u_axi_ro.rlast   = hmao_rlast;
  assign u_axi_ro.rvalid  = hmao_rvalid;

  // ===========================================================================
  // HELPER TASKS
  // ===========================================================================
  task automatic clear_irq();
    @(posedge hmao_clk); irq_clear <= 1'b1;
    @(posedge hmao_clk); irq_clear <= 1'b0;
    repeat(3) @(posedge hmao_clk);
  endtask

  task automatic run_hmao_engine(
    input  int          timeout_cy,
    output logic        ok,
    output logic        decision,
    output logic [7:0]  fault_bits
  );
    logic done;
    ok = 1'b0; decision = 1'b0; fault_bits = 8'h0;
    @(posedge hmao_clk); hmao_start <= 1'b1;
    @(posedge hmao_clk); hmao_start <= 1'b0;
    done = 1'b0;
    for (int c = 0; c < timeout_cy; c++) begin
      @(posedge hmao_clk);
      if (hmao_complete) begin done = 1'b1; break; end
    end
    @(posedge hmao_clk);
    if (done) begin
      ok = 1'b1; decision = hmao_decision; fault_bits = fault_out;
    end
  endtask

  // expected_label: 2=GRANT, 1=VETO, 0=BOUNDARY (log only, no assertion)
  task automatic run_collision_tc(
    input string tc_name, input string traj_hex, input string wm_hex,
    input string category, input real clearance_m, input int expected_label
  );
    logic hmao_ok, decision;
    logic [7:0] fault_bits;
    string traj_path, wm_path;

    traj_path = {`HEX_DIR, "/", traj_hex};
    wm_path   = {`HEX_DIR, "/", wm_hex};

    if (hmao_complete) clear_irq();

    $readmemh(traj_path, traj_mem);
    foreach (wm_mem[i]) wm_mem[i] = 32'h0;
    $readmemh(wm_path, wm_mem);
    @(posedge hmao_clk);

    run_hmao_engine(2_000_000, hmao_ok, decision, fault_bits);
    check({tc_name, "_complete"}, hmao_ok);

    if (hmao_ok) begin
      case (expected_label)
        2: begin
          $display("[%s] %s clearance=%0.2fm expect=GRANT got=%s faults=0x%02h",
                    tc_name, category, clearance_m, decision?"GRANT":"VETO", fault_bits);
          check({tc_name, "_expect_grant"}, decision == 1'b1);
        end
        1: begin
          $display("[%s] %s clearance=%0.2fm expect=VETO got=%s faults=0x%02h",
                    tc_name, category, clearance_m, decision?"GRANT":"VETO", fault_bits);
          check({tc_name, "_expect_veto"}, decision == 1'b0);
        end
        default: begin
          $display("[%s] %s clearance=%0.2fm BOUNDARY (no assert) got=%s faults=0x%02h viol=%016h",
                    tc_name, category, clearance_m, decision?"GRANT":"VETO", fault_bits, hmao_violation);
          if (decision) boundary_grant_cnt++; else boundary_veto_cnt++;
        end
      endcase
      // Regardless of label: watchdog must never spuriously fire on real data.
      check({tc_name, "_no_wdt_fault"}, (fault_bits & 8'h40) == 8'h00);
    end
    clear_irq();
  endtask

